import re

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    nodes = scope_nodes(doc, scope_node)
    products_table = next((n for n in nodes if n['kind'] == 'table' and 'Products' in n['title']), None)
    if not products_table:
        return []

    ents = []
    for row_idx, row in table_rows(products_table):
        prod_id = row.get('product')
        if prod_id:
            ents.append({"id": prod_id, "description": prod_id})
    return ents

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    nodes = scope_nodes(doc, scope_node)

    max_day = -1.0
    # Check daily ledger
    ledger_table = next((n for n in nodes if n['kind'] == 'table' and 'Daily ledger' in n['title']), None)
    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            try:
                max_day = max(max_day, float(row['day']))
            except (ValueError, KeyError):
                pass

    # Check order book tables
    for n in nodes:
        if n['kind'] == 'table' and 'Order book: Orders received and production planned' in n['title']:
            for row_idx, row in table_rows(n):
                try:
                    max_day = max(max_day, float(row['day']))
                except (ValueError, KeyError):
                    pass

    return max_day if max_day != -1.0 else None

def inputs(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    nodes = scope_nodes(doc, scope_node)
    inputs_list = []
    input_id_counter = 0

    # 1. Opening Stock
    prod_table = next((n for n in nodes if n['kind'] == 'table' and 'Products' in n['title']), None)
    if prod_table:
        for row_idx, row in table_rows(prod_table):
            input_id_counter += 1
            inputs_list.append({
                "id": f"inp_{input_id_counter}",
                "time": None,
                "kind": "opening_stock",
                "entities": [row['product']],
                "fields": {"opening_stock": float(row['opening stock'])},
                "src": [prod_table['node_id'], row_idx, ['product', 'opening stock']]
            })

    # 2. Daily Ledger Production and Orders
    ledger_table = next((n for n in nodes if n['kind'] == 'table' and 'Daily ledger' in n['title']), None)
    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            try:
                day = float(row['day'])
                prod_id = row['product']

                # Production
                prod_val = float(row['produced'])
                if prod_val > 0:
                    input_id_counter += 1
                    inputs_list.append({
                        "id": f"inp_{input_id_counter}",
                        "time": day,
                        "kind": "production",
                        "entities": [prod_id],
                        "fields": {"produced": prod_val},
                        "src": [ledger_table['node_id'], row_idx, ['day', 'product', 'produced']]
                    })

                # Orders
                ord_val = float(row['ordered'])
                if ord_val > 0:
                    input_id_counter += 1
                    inputs_list.append({
                        "id": f"inp_{input_id_counter}",
                        "time": day,
                        "kind": "order",
                        "entities": [prod_id],
                        "fields": {"ordered": ord_val},
                        "src": [ledger_table['node_id'], row_idx, ['day', 'product', 'ordered']]
                    })
            except (ValueError, KeyError):
                continue

    # 3. Order Book (Planned Production and Orders)
    for n in nodes:
        if n['kind'] == 'table' and 'Order book: Orders received and production planned' in n['title']:
            for row_idx, row in table_rows(n):
                try:
                    day = float(row['day'])
                    prod_id = row['product']

                    # Planned Production
                    pp_val = float(row['planned production'])
                    if pp_val > 0:
                        input_id_counter += 1
                        inputs_list.append({
                            "id": f"inp_{input_id_counter}",
                            "time": day,
                            "kind": "planned_production",
                            "entities": [prod_id],
                            "fields": {"planned_production": pp_val},
                            "src": [n['node_id'], row_idx, ['day', 'product', 'planned production']]
                        })

                    # Planned Orders
                    po_val = float(row['ordered'])
                    if po_val > 0:
                        input_id_counter += 1
                        inputs_list.append({
                            "id": f"inp_{input_id_counter}",
                            "time": day,
                            "kind": "planned_order",
                            "entities": [prod_id],
                            "fields": {"ordered": po_val},
                            "src": [n['node_id'], row_idx, ['day', 'product', 'ordered']]
                        })
                except (ValueError, KeyError):
                    continue

    return inputs_list

def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    nodes = scope_nodes(doc, scope_node)
    outcomes_list = []

    # 1. Daily Ledger
    ledger_table = next((n for n in nodes if n['kind'] == 'table' and 'Daily ledger' in n['title']), None)
    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            try:
                day = float(row['day'])
                prod_id = row['product']
                for field in ['shipped', 'backordered', 'stock']:
                    val = float(row[field])
                    outcomes_list.append({
                        "time": day,
                        "kind": f"daily_{field}",
                        "entities": [prod_id],
                        "value": val,
                        "src": [ledger_table['node_id'], row_idx, ['day', 'product', field]]
                    })
            except (ValueError, KeyError):
                continue

    # 2. Events List
    events_node = next((n for n in nodes if n['kind'] == 'list' and 'Events' in n['title']), None)
    if events_node:
        for line_idx, line in enumerate(events_node['lines']):
            match_day = re.search(r"Day (\d+)", line)
            if not match_day:
                continue
            day = float(match_day.group(1))

            # Find products mentioned in the line (entities identified in entities() function)
            ents_in_scope = [e['id'] for e in entities(doc, scope)]
            entities_found = [pid for pid in ents_in_scope if pid in line]

            event_kind = "event"
            if "dispatch capacity reached" in line:
                event_kind = "dispatch_capacity_reached"
            elif "runs out of stock" in line:
                event_kind = "out_of_stock"
            elif "fully backordered" in line:
                event_kind = "fully_backordered"
            elif "backlog cleared" in line:
                event_kind = "backlog_cleared"

            outcomes_list.append({
                "time": day,
                "kind": event_kind,
                "entities": entities_found,
                "value": None,
                "src": [events_node['node_id'], line_idx]
            })

    return outcomes_list

def params(doc, scope):
