def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    nodes = scope_nodes(doc, scope_node)
    outcomes_list = []

    # 1. Daily Ledger result quantities
    ledger = next((n for n in nodes if n['kind'] == 'table' and 'Daily ledger' in n['title']), None)
    if ledger:
        for row_idx, row in table_rows(ledger):
            try:
                day = float(row['day'])
                pid = row['product']
                for field in ['shipped', 'backordered', 'stock']:
                    val = float(row[field]) if row.get(field) else 0
                    outcomes_list.append({
                        "time": day,
                        "kind": f"daily_{field}",
                        "entities": [pid],
                        "value": val,
                        "src": [ledger['node_id'], row_idx, ['day', 'product', field]]
                    })
            except (ValueError, KeyError):
                continue

    # 2. Events List
    events_node = next((n for n in nodes if n['kind'] == 'list' and 'Events' in n['title']), None)
    if events_node:
        ents_in_scope = [e['id'] for e in entities(doc, scope)]
        for line_idx, line in enumerate(events_node['lines']):
            match_day = re.search(r"Day (\d+)", line)
            if not match_day:
                continue
            day = float(match_day.group(1))

            entities_found = [pid for pid in ents_in_scope if pid in line]

            event_kind = "generic_event"
            if "dispatch capacity reached" in line:
                event_kind = "dispatch_capacity_reached"
            elif "runs out of stock" in line:
                event_kind = "out_of_stock"
            elif "fully backordered" in line:
                event_kind = "fully_backordered"
            elif "backlog cleared" in line:
                event_kind = "backlog_cleared"

            outcomes_list.append({
                "time": day,
                "kind": event_kind,
                "entities": entities_found,
                "value": None,
                "src": [events_node['node_id'], line_idx]
            })

    # 3. Order book Open orders (backordered)
    for n in nodes:
        if n['kind'] == 'table' and 'Order book: Open orders' in n['title']:
            # Extract day from title: "Open orders at the end of day 70"
            day_match = re.search(r"day (\d+)", n['title'])
            day = float(day_match.group(1)) if day_match else None
            for row_idx, row in table_rows(n):
                pid = row.get('product')
                if pid:
                    try:
                        val = float(row['units still open']) if row.get('units still open') else 0
                        outcomes_list.append({
                            "time": day,
                            "kind": "end_of_period_backorder",
                            "entities": [pid],
                            "value": val,
                            "src": [n['node_id'], row_idx, ['product', 'units still open']]
                        })
                    except ValueError:
                        continue

    return outcomes_list

def params(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    text = ""
    if scope_node['kind'] == 'text':
        text = scope_node['text']
    else:
        # In case it's a different node type, check children
        for n in scope_nodes(doc, scope_node):
            if n['kind'] == 'text':
                text += n['text'] + " "

    match = re.search(r"Daily dispatch capacity:\s*([\d,]+)", text)
    if match:
        cap_val = float(match.group(1).replace(',', ''))
        return {"daily_dispatch_capacity": cap_val}

    return {}
